import java.util.*;
abstract class Seat{String seatId;Seat(String s){seatId=s;}public String getSeatId(){return seatId;}public abstract double getPrice();}class RegularSeat extends Seat{RegularSeat(String i){super(i);}public double getPrice(){return 150;}}class PremiumSeat extends Seat{PremiumSeat(String i){super(i);}public double getPrice(){return 250;}}class ReclinerSeat extends Seat{ReclinerSeat(String i){super(i);}public double getPrice(){return 400;}}class Customer{String name;Customer(String n){name=n;}}
class Show{private Set<String> bookedSeats=new HashSet<>();private boolean started=false;public Booking book(Customer c,Seat...s){if(s.length==0||s.length>6){System.out.println("Booking must contain 1 to 6 seats.");return null;}Set<String> req=new HashSet<>();for(Seat x:s)if(bookedSeats.contains(x.getSeatId())||!req.add(x.getSeatId())){System.out.println("Seat "+x.getSeatId()+" is already booked for this show.");return null;}if(started){System.out.println("Booking unavailable: show has started.");return null;}bookedSeats.addAll(req);Booking b=new Booking(c,this,s);b.printConfirmation();return b;}public void releaseSeats(Seat[]s){for(Seat x:s)bookedSeats.remove(x.getSeatId());}public void startShow(){started=true;}public boolean hasStarted(){return started;}}
class Booking{private Customer customer;private Show show;private Seat[] seats;private boolean cancelled=false;Booking(Customer c,Show s,Seat[] a){customer=c;show=s;seats=a.clone();}public double getTotal(){double t=0;for(Seat s:seats)t+=s.getPrice();return t;}public void printConfirmation(){System.out.print("Booking confirmed for "+customer.name+": ");for(int i=0;i<seats.length;i++){System.out.print(seats[i].getSeatId());if(i<seats.length-1)System.out.print(", ");}System.out.printf(". Total: ₹%.2f.%n",getTotal());}public void cancel(){if(cancelled){System.out.println("Booking already cancelled.");return;}if(show.hasStarted()){System.out.println("Cannot cancel: show has started.");return;}show.releaseSeats(seats);cancelled=true;System.out.println(customer.name+"'s booking cancelled.");System.out.print("Seats ");for(int i=0;i<seats.length;i++){System.out.print(seats[i].getSeatId());if(i<seats.length-1)System.out.print(", ");}System.out.println(" released.");}}
public class CampusPremiere{public static void main(String[] args){Show s=new Show();Customer a=new Customer("Asha"),r=new Customer("Ravi"),n=new Customer("Neha");Booking b=s.book(a,new RegularSeat("A1"),new RegularSeat("A2"),new PremiumSeat("F5"));s.book(r,new RegularSeat("A2"));s.book(r,new ReclinerSeat("R1"));b.cancel();s.book(n,new RegularSeat("A2"));}}